<!doctype html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>WhatsApp Settings - Happy Cow Animal Feeds</title>
    <link rel="icon" type="image/svg+xml" href="favicon.svg"><link rel="stylesheet" href="assets/css/style.css?v=20261011-3"><link rel="stylesheet" href="assets/css/mobile-responsive.css?v=20260903-2"></head>
<body><div class="container"><div class="main-content"><main class="page-content"><div class="page-header"><h1>WhatsApp Settings</h1><a class="btn" href="index.php">Back to Dashboard</a></div><div class="content-box"><p>Choose a provider and enter its API details. Keep access tokens private.</p><form id="whatsappForm"><div class="form-row"><div class="form-group"><label for="provider">Provider</label><select id="provider"><option value="cloud_api">Meta WhatsApp Cloud API</option><option value="twilio">Twilio</option><option value="africastalking">Africa's Talking</option></select></div><div class="form-group"><label for="fromNumber">Business WhatsApp Number</label><input id="fromNumber" type="tel" value="0797251258"></div></div><div class="form-row"><div class="form-group"><label for="apiKey">Access Token / API Key</label><input id="apiKey" type="password"></div><div class="form-group"><label for="apiSecret">API Secret</label><input id="apiSecret" type="password"></div></div><div class="form-group"><label for="phoneNumberId">Phone Number ID</label><input id="phoneNumberId" placeholder="Required for Meta Cloud API"></div><label><input type="checkbox" id="enabled"> Enable WhatsApp</label><label><input type="checkbox" id="sendReceipts" checked> Send receipts</label><label><input type="checkbox" id="sendAlerts" checked> Send alerts</label><p id="message" class="alert" hidden></p><button class="btn btn-primary" type="submit">Save WhatsApp Settings</button></form></div></main></div></div><script>const form=document.getElementById('whatsappForm'),message=document.getElementById('message');fetch('api/get_whatsapp_settings.php').then(r=>r.json()).then(d=>{if(d.success){const s=d.settings;provider.value=s.provider||'cloud_api';fromNumber.value=s.from_number||'0797251258';phoneNumberId.value=s.phone_number_id||'';enabled.checked=String(s.enabled)==='1';sendReceipts.checked=String(s.send_receipts)!=='0';sendAlerts.checked=String(s.send_alerts)!=='0';}}).catch(()=>{});form.addEventListener('submit',e=>{e.preventDefault();const d={provider:provider.value,api_key:apiKey.value,api_secret:apiSecret.value,phone_number_id:phoneNumberId.value,from_number:fromNumber.value,enabled:enabled.checked?1:0,send_receipts:sendReceipts.checked?1:0,send_alerts:sendAlerts.checked?1:0};fetch('api/save_whatsapp_settings.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(d)}).then(r=>r.json()).then(d=>{message.hidden=false;message.textContent=d.message;message.className='alert alert-'+(d.success?'success':'error');});});</script></body></html>
